&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;ABOUT FORM3&amp;nbsp;💭&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;Revolutionising the world of payments with our cloud-native, multi-cloud platform. For more information about Form3, check out the following pages:&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;a href=&quot;https://www.form3.tech/platform&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;What we do&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;|&amp;nbsp;&lt;/span&gt;&lt;a href=&quot;https://www.form3.tech/culture&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Life at Form3&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;|&amp;nbsp;&lt;/span&gt;&lt;a href=&quot;https://www.youtube.com/@Form3Cloud/podcasts&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;P&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;ayments Cannot&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Fail&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Series&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;|&amp;nbsp;&lt;/span&gt;&lt;a href=&quot;https://techpodcast.form3.tech/episodes&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;.Tech&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;&amp;nbsp;Podcast&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;OUR DEI&amp;amp;B COMMITMENT&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;We hire talented people from a variety of backgrounds and experiences and are committed to a work environment based on diversity, open-mindedness and curiosity. We’re united by our company values (we even created them together!) and we celebrate our unique differences.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;Our employee lifecycle processes are designed to embrace equal opportunity and prevent discrimination against our people regardless of personal characteristics. It is our strong belief that the more inclusive and belonging we are as a business, the better our work will be.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;As an inclusive employer, we guarantee to interview all neurodiverse and physically disabled applicants who meet the minimum criteria for this role. We also encourage candidates to notify us of any reasonable adjustments that may be required during the recruitment process. This includes providing job adverts in alternative, accessible formats or adjustments required at interview stage.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;If you consider yourself to be neurodiverse or physically disabled under the UN definition of disability and would like to be considered under this scheme and/or require any reasonable adjustments please let us know by sending an email to &lt;/span&gt;&lt;a ----- ----- data-contrast=&quot;none&quot;&gt; clearly stating your consent for us to process this data. &lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;For more information please refer to our &lt;/span&gt;&lt;a href=&quot;https://www.form3.tech/legal/recruitment-data-policy&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Recruitment Data Policy&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;none&quot;&gt;.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.co.uk">Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;From Fivetran’s founding until now, our mission has remained the same: to make access to data as simple and reliable as electricity. With Fivetran, customer data arrives in their warehouses, canonical and ready to query, with no engineering or maintenance required. We’re proud that more organizations continue to leverage our technology every day to become truly data-driven.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;About Us&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;br&gt;Fivetran and dbt Labs are bringing together two industry-leading companies with a shared mission: helping organizations unlock the full value of their data.&lt;br&gt;&lt;br&gt;Together, we’re delivering the data infrastructure layer that helps organizations move, transform, and trust their data — from the moment data moves, through every transformation, to the context teams and AI systems rely on.&lt;br&gt;&lt;br&gt;Fivetran helps organizations automate data movement across the systems, clouds, engines, and tools they rely on. dbt Labs pioneered analytics engineering, helping teams transform data into reliable, governed insights. Together, we support thousands of organizations as they build a trusted foundation for analytics, AI, and better business decisions.&lt;br&gt;&lt;br&gt;As we bring our teams and technology together, we’re building on the strengths of both companies while continuing to deliver the products and experiences our customers know and trust. It’s an exciting time to join us: we’re creating a company with the scale, talent, and technology to help more organizations put their data to work with greater speed, confidence, and impact.&lt;br&gt;&lt;br&gt;During this transition period, you may see references to both Fivetran and dbt Labs throughout our recruiting process as we integrate our teams, systems, and career sites.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About the Role&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Fivetran is building data pipelines to power the modern data stack for thousands of companies.&lt;/p&gt;
&lt;p&gt;We’re looking for a talented Senior Sales Engineer to join our Enterprise sales team. As an Enterprise Sales Engineer, you will work closely with our sales team to understand our Enterprise customers’ complex business needs and showcase how Fivetran’s and dbt Labs&#39; solutions can help them achieve their desired business outcomes. You will be responsible for providing technical expertise, identifying technical requirements, and ensuring a successful proof-of value throughout the sales cycle&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;color: #494949;&quot;&gt;This is a full-time position based&lt;/span&gt; remotely in Dublin or London.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Technologies You’ll Use&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;color: #494949;&quot;&gt;AWS, GCP, Azure, Snowflake, BigQuery, Databricks, New Relic, Linux, Windows, Python, Jav&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;color: rgb(0, 0, 0);&quot;&gt;&lt;strong&gt;What You’ll Do&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;color: #494949 !important;&quot;&gt;&lt;span style=&quot;color: #494949;&quot;&gt;Work with Enterprise customers to understand their business, their use cases, and their data replication requirements&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: #494949 !important;&quot;&gt;&lt;span style=&quot;color: #494949;&quot;&gt;Develop and deliver technical presentations to Enterprise audiences&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: #494949 !important;&quot;&gt;&lt;span style=&quot;color: #494949;&quot;&gt;Ensure the technical win by running an organized proof-of-value process&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: #494949 !important;&quot;&gt;&lt;span style=&quot;color: #494949;&quot;&gt;Work closely with multiple cross-fuctional organizations driving change and improvements to Fivetran as a whole.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: #494949 !important;&quot;&gt;&lt;span style=&quot;color: #494949;&quot;&gt;Work closely with multiple Sales representatives, while maintaining a high level of customer focus and technical excellence&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: #494949 !important;&quot;&gt;&lt;span style=&quot;color: #494949;&quot;&gt;Stay up-to-date on the latest technologies and trends in our industry&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: #494949 !important;&quot;&gt;&lt;span style=&quot;color: #494949;&quot;&gt;Assist team members in advanced technical or business roadblocks&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;color: rgb(0, 0, 0);&quot;&gt;&lt;strong&gt;Skills We’re Looking For&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;color: #494949 !important;&quot;&gt;&lt;span style=&quot;color: #494949;&quot;&gt;5+ years in data replication, sales engineering, or related technical field&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: #494949 !important;&quot;&gt;&lt;span style=&quot;color: #494949;&quot;&gt;Strong technical background covering database replication, cloud infrastructure, and data replication technologies with some form of hands on experience&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: #494949 !important;&quot;&gt;&lt;span style=&quot;color: #494949;&quot;&gt;Hands on experience with DBT&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: #494949 !important;&quot;&gt;&lt;span style=&quot;color: #494949;&quot;&gt;Experience with modern data analytics technologies, including cloud data warehouses, transformation tooling, data catalogs, and BI tools&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: #494949 !important;&quot;&gt;&lt;span style=&quot;color: #494949;&quot;&gt;Excellent communication and presentation skills with a keen ability to explain complex technical concepts to both technical and non-technical stakeholders&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: #494949 !important;&quot;&gt;&lt;span style=&quot;color: #494949;&quot;&gt;Strong problem-solving and analytical skills&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: #494949 !important;&quot;&gt;&lt;span style=&quot;color: #494949;&quot;&gt;Experience with Oracle, SQL Server, Postgres, MySQL, and NoSQL databases&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: #494949 !important;&quot;&gt;&lt;span style=&quot;color: #494949;&quot;&gt;Hands on experience with other data replication or ETL tools&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: #494949 !important;&quot;&gt;&lt;span style=&quot;color: #494949;&quot;&gt;Experience with self-hosted software applications and supporting infrastructure&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: #494949 !important;&quot;&gt;&lt;span style=&quot;color: #494949;&quot;&gt;Hands on networking experience both in the cloud and on-premise&lt;br&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;color: rgb(0, 0, 0);&quot;&gt;&lt;strong&gt;(Optional) Bonus Skills​&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;color: #494949 !important;&quot;&gt;&lt;span style=&quot;color: #494949;&quot;&gt;Experience developing partner relationships&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: #494949 !important;&quot;&gt;&lt;span style=&quot;color: #494949;&quot;&gt;Specialized expertise in security posture&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: #494949 !important;&quot;&gt;&lt;span style=&quot;color: #494949;&quot;&gt;Experience with self-hosted and SaaS software applications&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: #494949 !important;&quot;&gt;&lt;span style=&quot;color: #494949;&quot;&gt;Docker/Podman/Kubernetes experience&lt;br&gt;&lt;br&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p class=&quot;p1&quot;&gt;#LI-Remote &lt;span data-sheets-root=&quot;1&quot;&gt;#LI-LA1&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p class=&quot;p-rich_text_section&quot; style=&quot;line-height: 1.3;&quot;&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;Perks and Benefits&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;100% employer-paid medical insurance&lt;strong&gt;*&lt;/strong&gt;&lt;/li&gt;
&lt;li data-pm-slice=&quot;1 1 []&quot;&gt;Generous paid time away from work, including paid vacation or flexible/unlimited vacation depending on role and country, plus paid sick time, inclusive parental leave, paid holidays, including a year-end Global Week of Rest, and volunteer days off.&lt;/li&gt;
&lt;li&gt;RSU stock grants*&lt;/li&gt;
&lt;li&gt;Professional development and training opportunities&lt;/li&gt;
&lt;li&gt;Company virtual happy hours, free food, and fun team-building activities&lt;/li&gt;
&lt;li&gt;Monthly cell phone stipend&lt;/li&gt;
&lt;li&gt;Access to an innovative mental health support platform that offers personalized care and resources in areas such as: therapy, coaching, and self-guided mindfulness exercises for all covered employees and their covered dependents.&lt;/li&gt;
&lt;/ul&gt;
&lt;p style=&quot;line-height: 1.3;&quot;&gt;&lt;em&gt;&lt;strong&gt;*&lt;/strong&gt;May vary by country and worker type - please reach out to your recruiter for more information&lt;/em&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1.3;&quot;&gt;&lt;em&gt;Click &lt;a href=&quot;https://drive.google.com/drive/folders/1CdawUwjo1Q1B7ghZJ_owdmmHB8VtqhBu?usp=sharing&quot; target=&quot;_blank&quot;&gt;here&lt;/a&gt; to learn more about Fivetran&#39;s Benefits by Region.&lt;/em&gt;&lt;/p&gt;
&lt;hr&gt;
&lt;p style=&quot;line-height: 1.3;&quot;&gt;We’re honored to be &lt;a class=&quot;c-link&quot; href=&quot;https://fivetran.com/blog/hvr-acquisition-series-d&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://fivetran.com/blog/hvr-acquisition-series-d&quot; data-sk=&quot;tooltip_parent&quot;&gt;valued at over $5.6 billion&lt;/a&gt;, but more importantly, we’re proud of our&amp;nbsp;&lt;a class=&quot;c-link&quot; href=&quot;https://fivetran.com/culture&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://fivetran.com/culture&quot; data-sk=&quot;tooltip_parent&quot;&gt;core values of Get Stuck In, Do the Right Thing, and One Team, One Dream&lt;/a&gt;. Read about us in&amp;nbsp;&lt;a class=&quot;c-link&quot; href=&quot;https://fivetran-com.s3.amazonaws.com/news/forbes-aug-sept-2022-digital-reprint-10-21-22.pdf&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://fivetran-com.s3.amazonaws.com/news/forbes-aug-sept-2022-digital-reprint-10-21-22.pdf&quot; data-sk=&quot;tooltip_parent&quot;&gt;Forbes&lt;/a&gt;.&amp;nbsp; &amp;nbsp; &amp;nbsp;&lt;/p&gt;
&lt;p style=&quot;line-height: 1.3;&quot;&gt;Fivetran brings together high-quality talent across the globe to make data access as easy and reliable as electricity for our customers. We value and recognize that our customers benefit from having innovative teams made of people from many backgrounds, experiences, and identities. Fivetran promotes diversity, equity, inclusion &amp;amp; belonging through attracting, recruiting, developing, and retaining a diverse workforce, not only because it is the right thing to do, but because it helps us build a world-class company to better serve our customers, our people and our communities.&lt;/p&gt;
&lt;p style=&quot;line-height: 1.3;&quot;&gt;To learn more about Fivetran’s culture and what it’s like to be part of the team, &lt;a href=&quot;https://www.youtube.com/watch?v=xlhtp4dGh8o&quot; target=&quot;_blank&quot;&gt;click here&lt;/a&gt; and enjoy our video.&lt;/p&gt;
&lt;p style=&quot;line-height: 1.3;&quot;&gt;To learn more about our candidate privacy policy, you can &lt;a href=&quot;https://fivetran.com/candidate-privacy&quot; target=&quot;_blank&quot;&gt;read our statement here&lt;/a&gt;.&lt;/p&gt;
&lt;hr&gt;
&lt;p style=&quot;line-height: 1.3;&quot;&gt;&lt;em&gt;We are committed to ensuring that all candidates have an equal opportunity to participate in our interview process. If you require accommodations at any stage of the process due to a disability, medical condition, or any other circumstance, please don&#39;t hesitate to submit your request by filling out this &lt;a href=&quot;https://forms.gle/V7k3t4u9j523XkEt6&quot;&gt;form&lt;/a&gt;. We will work with you to provide reasonable accommodations to facilitate your participation and ensure a fair and accessible interview experience. Your request and any information provided will be kept confidential and will not impact your candidacy. We look forward to hearing from you and accommodating your needs to the best of our ability.&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.co.uk">Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;Who we are&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At Twilio, we’re shaping the future of communications, all from the comfort of our homes. We deliver innovative solutions to&lt;a class=&quot;c-link&quot; href=&quot;https://customers.twilio.com/&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://customers.twilio.com/&quot; data-sk=&quot;tooltip_parent&quot;&gt;&amp;nbsp;hundreds of thousands of businesses&amp;nbsp;&lt;/a&gt;and empower millions of developers worldwide to craft personalized customer experiences.&lt;/p&gt;
&lt;p&gt;Our dedication to &lt;a class=&quot;c-link&quot; href=&quot;https://www.twilio.com/en-us/blog/open-work&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://www.twilio.com/en-us/blog/open-work&quot; data-sk=&quot;tooltip_parent&quot;&gt;remote-first work&lt;/a&gt;, and strong culture of connection and global inclusion means that no matter your location, you’re part of a vibrant team with diverse experiences making a global impact each day. As we continue to revolutionize how the world interacts, we’re acquiring new skills and experiences that make work feel truly rewarding. Your career at Twilio is in your hands.&lt;br&gt;&lt;span style=&quot;color: rgb(255, 255, 255);&quot;&gt;.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Hiring and how we work&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We use Artificial Intelligence (AI) to help make our hiring process efficient. That said, every hiring decision is made by real Twilions!&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Also, while we are a remote-first company, you may be asked to report in person on an ad-hoc basis for team gatherings, functional off-sites or customer meetings.&amp;nbsp;&lt;br&gt;&lt;span style=&quot;color: rgb(255, 255, 255);&quot;&gt;.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;See yourself at Twilio&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Join the team as Twilio’s next &lt;strong&gt;Security Engineer, Incident Response&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About the job&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The Security Incident Response Team (SIRT) is looking for a Security Engineer who is passionate about solving Twilio’s mission of security and reliability by working across the organization to lead the technical response to security events and incidents across Twilio’s global infrastructure, services and applications by effectively conducting triage, containment, remediation and driving post-incident betterments.&amp;nbsp; You will work within a team that partners with R&amp;amp;D Engineering and R&amp;amp;D Business teams to develop scalable processes and technical solutions.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;You will be a valued member of a team of deeply technical Security Engineers to focus on creating bespoke and standard Security response processes, enhancing our capabilities for threat mitigation and incident response, and then automating as much as you possibly can (and more)! You will help us to grow our global, scaled team and program.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Responsibilities&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;In this role, you’ll:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Lead and support the response to all security events and incidents across Twilio’s complex global infrastructure, services and applications.&lt;/li&gt;
&lt;li&gt;Be responsible for documentation of incidents and projects you work on and craft best practices as runbooks and standard operating procedures to share knowledge across teams.&lt;/li&gt;
&lt;li&gt;Work cross-collaboratively to understand and help solve challenges related to a broad spectrum of threat actors and activity.&lt;/li&gt;
&lt;li&gt;Work to improve Twilio’s security and reliability posture by driving identified betterments from security events and incidents.&lt;/li&gt;
&lt;li&gt;Rapidly acquire new technical skills and knowledge in a fast-paced, highly disruptive industry environment.&lt;/li&gt;
&lt;li&gt;Own the security incident lifecycle, respond to incidents and participate in on-call rotation and participate in RCAs for security incidents.&lt;/li&gt;
&lt;li&gt;Build, cultivate, and maintain positive relationships with internal customers to identify and facilitate solutions to increase the impact of the team’s work.&lt;/li&gt;
&lt;li&gt;Provide mentorship, support, and care for the team in a way that enables long-term career development, happiness, and success at scale.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Qualifications&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Twilio values diverse experiences from all kinds of industries, and we encourage everyone who meets the required qualifications to apply. If your career is just starting or hasn&#39;t followed a traditional path, don&#39;t let that stop you from considering Twilio. We are always looking for people who will bring something new to the table!&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Required:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Proven experience: 3+ years of security incident response in a production-cloud environment&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Subject-matter expert on security issues and technologies&lt;/li&gt;
&lt;li&gt;Ability to utilize AI for comprehensive, complex security incident response activities delivering high fidelity detections&lt;/li&gt;
&lt;li&gt;Advanced knowledge of service-oriented architectures, as well as experience with security tools and technologies fit for a cloud environment&lt;/li&gt;
&lt;li&gt;Experience working across a technology stack on difficult security challenges and initiatives&lt;/li&gt;
&lt;li&gt;Experience with SIEM platforms and the ability to extend their functionality&lt;/li&gt;
&lt;li&gt;Experience with SOAR tools and automating manual security processes&lt;/li&gt;
&lt;li&gt;Experience in either AWS, GCP, or other large cloud platform&lt;/li&gt;
&lt;li&gt;Excellent written and verbal communication skills&lt;/li&gt;
&lt;li&gt;Ability to influence and build effective working relationships with every level of the organization.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Desired:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;AI Model Security &amp;amp; Posture Management: Support Implementation of&amp;nbsp; controls and safeguards to prevent AI vulnerabilities, such as prompt injections, model evasion, and data poisoning&lt;/li&gt;
&lt;li&gt;AI-Driven Threat Response: Utilize GenAI and LLM-based security use cases to rapidly interpret alerts, reduce false positives, and contextualize threat data&lt;/li&gt;
&lt;li&gt;Artifact &amp;amp; Evidence Triage: Collects intrusion artifacts and forensically sound images to analyze malware, trojans, and source code.&lt;/li&gt;
&lt;li&gt;Threat Intelligence Integration: Monitors external vendor data and threat intelligence to analyze trends and proactively defend against emerging risks.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Location&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;This role will be remote, and based in Ireland or U.K.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Travel&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We prioritize connection and opportunities to build relationships with our customers and each other. For this role, you may be required to travel occasionally to participate in project or team in-person meetings.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What We Offer&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Working at Twilio offers many benefits, including competitive pay, generous time off, ample parental and wellness leave, healthcare, a retirement savings program, and much more. Offerings vary by location.&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;Twilio thinks big. Do you?&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We like to solve problems, take initiative, pitch in when needed, and are always up for trying new things. That&#39;s why we seek out colleagues who embody our values — something we call &lt;a href=&quot;https://www.twilio.com/company/values&quot;&gt;Twilio Magic&lt;/a&gt;. Additionally, we empower employees to build &lt;a href=&quot;https://twilio.org/support-and-resources/impact-fund&quot;&gt;positive change in their communities&lt;/a&gt; by supporting their volunteering and donation efforts.&lt;/p&gt;
&lt;p&gt;So, if you&#39;re ready to unleash your full potential, do your best work, and be the best version of yourself, apply now! If this role isn&#39;t what you&#39;re looking for, &lt;a href=&quot;https://www.twilio.com/company/jobs#open-positions&quot;&gt;please consider other open positions.&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;color: rgb(255, 255, 255);&quot;&gt;.&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Stay alert to recruitment fraud&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We care about your safety. Scammers sometimes impersonate Twilio recruiters through fake job postings, emails, websites, or messages. Please ensure you are engaging with an official @&lt;a href=&quot;http://twilio.com&quot;&gt;twilio.com&lt;/a&gt; email address. We will never ask for payment, gift cards, cryptocurrency, or banking information during the recruiting process. We do not make job offers without a formal interview process or conduct interviews exclusively through text-based messaging apps.&lt;br&gt;&lt;br&gt;&lt;span style=&quot;color: rgb(255, 255, 255);&quot;&gt;.&lt;/span&gt;&lt;strong&gt; &lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Twilio is proud to be an equal opportunity employer.&lt;/strong&gt; We do not discriminate based upon race, religion, color, national origin, sex (including pregnancy, childbirth, reproductive health decisions, or related medical conditions), sexual orientation, gender identity, gender expression, age, status as a protected veteran, status as an individual with a disability, genetic information, political views or activity, or other applicable legally protected characteristics. We also consider qualified applicants with criminal histories, consistent with applicable federal, state and local law. Qualified applicants with arrest or conviction records will be considered for employment in accordance with the Los Angeles County Fair Chance Ordinance for Employers and the California Fair Chance Act. Additionally, Twilio participates in the E-Verify program in certain locations, as required by law.&lt;/p&gt;&lt;/div&gt;<p>Find more <a href="https://www.arbeitnow.co.uk/english-speaking-jobs">English Speaking Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;h3&gt;About the Position&lt;/h3&gt;
&lt;p&gt;We’re looking for Software Engineers who want to help us design and build the systems and tools that run the firm. You’ll find Software Engineers in all parts of Jane Street, solving real problems in critical areas ranging from trading desks to our accounting team, as well as building foundational infrastructure, whether that means implementing network monitoring or risk models.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;We are big believers in functional programming and, using OCaml, a statically -typed functional programming language, as our primary tool. More recently, Python has become a vital part of Jane Street’s research and trading work, acting as the go-to language for data analysis, visualization, and machine learning.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Beyond our own environment, we also recognize the value of open source software, leveraging it in our daily work and releasing over a million lines of our own code as open source. We’re also always looking for ways to expand open source projects, and provide ongoing support to things like Mercurial, the OCaml compiler, and the OPAM package manager. That said, we’re interested in talented engineers with experience in any language—most of us came in with little to no practical experience in OCaml before we joined.&lt;/p&gt;
&lt;p&gt;If you’d like to learn more, you can read about our &lt;a href=&quot;https://blog.janestreet.com/applying-to-jane-street/&quot;&gt;interview process&lt;/a&gt; and meet some of our &lt;a href=&quot;https://www.janestreet.com/join-jane-street/get-to-know-us/&quot;&gt;newest hires&lt;/a&gt;.&lt;/p&gt;
&lt;h3&gt;About You&lt;/h3&gt;
&lt;p&gt;We &lt;em&gt;don’t&lt;/em&gt; expect you to have a background in functional programming, OCaml, Python, finance, or any other specific field—we’re looking for smart programmers who enjoy solving interesting problems. We’re more interested in how you think and learn than what you currently know. You should be:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;A top-notch programmer with a love for technology&lt;/li&gt;
&lt;li&gt;Intellectually curious, collaborative, and eager to learn&lt;/li&gt;
&lt;li&gt;Humble and unafraid to ask questions and admit mistakes&lt;/li&gt;
&lt;li&gt;Fluent in English&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;If you&#39;d like to get an idea of what we cover in our software engineering interview process, you can visit our &lt;a href=&quot;https://www.janestreet.com/preparing-for-a-software-engineering-interview/&quot;&gt;interview prep page&lt;/a&gt;.&lt;/p&gt;
&lt;p&gt;&lt;em&gt;If you&#39;re a recruiting agency and want to partner with us, please reach out to -----<p>Find <a href="https://www.arbeitnow.co.uk">Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;h3&gt;About the position&lt;/h3&gt;
&lt;p&gt;We&#39;re looking to add a passionate Cybersecurity Engineer to our London office to help protect Jane Street’s employees, data, and infrastructure from the wilds of the internet. Our Cybersecurity Engineers are responsible for developing and using monitoring tools to guard the firm, as well as handling incident response and remediation when a threat is found.&lt;/p&gt;
&lt;p&gt;Our Cybersecurity team is a skilled group of programmers and security experts who are dedicated to keeping the firm safe. We consider ourselves to be tapped into developments in the broader cybersecurity space, and can tell the difference between the latest cool hack by security researchers and what actually matters in our day-to-day. In this role, you’ll carefully consider the context of our decisions as we think about the tradeoffs we’re making in our approach to resolving cybersecurity issues. We’ll expect you to apply a methodical approach to performing unstructured investigations to locate and repair the source of a security issue.&lt;/p&gt;
&lt;p&gt;You will also act as an ambassador of best practices to the rest of the firm. Team members understand and practice good personal cybersecurity hygiene, and are able to talk to others about it. A key component of doing well in this position is bringing everyone else along with you on the cybersecurity journey, and you should be excited to learn from your colleagues and pass that learning on to new analysts.&lt;/p&gt;
&lt;h3&gt;About you&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Graduating with a Bachelor’s degree in Computer Science, Engineering, Information Systems, or a related field&lt;/li&gt;
&lt;li&gt;An avid follower of cybersecurity news&lt;/li&gt;
&lt;li&gt;A strong programmer who can demonstrate high potential and an aptitude for learning&lt;/li&gt;
&lt;li&gt;Comfortable and interested in managing your code and configs in version control, and knowledge of your editor (we don&#39;t care which though)&lt;/li&gt;
&lt;li&gt;Familiar with threat modeling, and able to clearly communicate your understanding of the tradeoffs we’re making to internal stakeholders&lt;/li&gt;
&lt;li&gt;Able to explain the cybersecurity decisions you’ve made in your own life, and how you’ve approached thinking about those decisions&lt;/li&gt;
&lt;li&gt;Able to adapt to changing scenarios and make challenging decisions under pressure&lt;/li&gt;
&lt;li&gt;Humble attitude about what you know and don’t know; not afraid to ask questions and admit mistakes&lt;/li&gt;
&lt;li&gt;Curious problem solver with a positive, collaborative attitude&lt;/li&gt;
&lt;li&gt;Fluent in English&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;em&gt;If you&#39;re a recruiting agency and want to partner with us, please reach out to -----
&lt;p&gt;&amp;nbsp;&lt;/p&gt;<p>Find more <a href="https://www.arbeitnow.co.uk/english-speaking-jobs">English Speaking Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;span class=&quot;TextRun SCXW107525881 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW107525881 BCX8&quot;&gt;At Dragos, the mission is personal. The systems we protect deliver the water you drink, power your home, and keep the hospitals your community depends on running. Those critical infrastructure systems that power our civilization around the world are under attack every day by adversaries. When those systems fail, people are&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW107525881 BCX8&quot;&gt;immediately&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW107525881 BCX8&quot;&gt;&amp;nbsp;at risk.&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW107525881 BCX8&quot;&gt;We are the global leader in&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW107525881 BCX8&quot;&gt;xOT&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW107525881 BCX8&quot;&gt;&amp;nbsp;cybersecurity, combining technology, threat intelligence, and expert services. The people here chose this work because they understand&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW107525881 BCX8&quot;&gt;what is&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW107525881 BCX8&quot;&gt;&amp;nbsp;at stake&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW107525881 BCX8&quot;&gt;. Here, you will find a remote-first mission-driven team across North America, Europe, the Middle East, and APAC built on authenticity, transparency, and trust. If safeguarding the systems that protect your family, friends, and community is the kind of work that matters to you, you are in the right place.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW107525881 BCX8&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:120,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;About the Role&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;As a Senior OT Security Analyst on the &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;OT Watch Complete&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; team, you will help lead a frontline monitoring and triage unit responsible for identifying potential adversary activity in customer operational technology (OT) environments. You will work closely with other experienced industrial defenders and mentor junior analysts to investigate anomalous network behaviors, validate detection triggers, and support threat hunters and incident responders with high-quality escalations. You will also operate and maintain the Dragos platform on behalf of customers, helping manage vulnerabilities, tune detections, properly classify OT assets, and provide input on response recommendations.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:279}&quot;&gt; This is a great opportunity for experienced cybersecurity professionals — especially those passionate about industrial security — to build hands-on experience in active OT security operations.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Responsibilities&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Lead shift operations, guiding analysts as they triage detection alerts and network telemetry from the Dragos Platform across customer OT environments — stepping in as shift leader for your region when needed.&lt;/li&gt;
&lt;li&gt;Serve as a senior investigator, digging into suspicious activity to identify misconfigurations, anomalies, and potential malicious behavior across industrial networks.&lt;/li&gt;
&lt;li&gt;Apply deep analysis and context to escalate findings to Incident Responders and threat hunters with clear, actionable documentation.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Partner across teams — analysts, threat hunters, incident responders, platform engineers, and Detection Engineering — to tune detection logic, reduce false positives, and shape new Dragos Platform detections and playbooks.&lt;/li&gt;
&lt;li&gt;Write and deliver incident summaries and operational reports that give internal stakeholders and customers a clear read on what&#39;s happening in their environment.&lt;/li&gt;
&lt;li&gt;Support the full scope of OT Watch Complete, from asset classification and vulnerability management to hardening recommendations and direct customer information requests.&lt;/li&gt;
&lt;li&gt;Build expertise continuously in ICS/OT protocols, adversary tradecraft, and threat intelligence specific to industrial environments.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Qualifications&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;:&lt;/span&gt; &lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;3–5 years of experience in network security, ideally with hands-on exposure to real-world threat investigation.&lt;/li&gt;
&lt;li&gt;Solid understanding of core networking concepts — TCP/IP, firewalls, DNS, packet analysis.&lt;/li&gt;
&lt;li&gt;Hands-on experience with security monitoring tools, such as IDS/IPS, SIEM platforms, or network traffic analyzers.&lt;/li&gt;
&lt;li&gt;Strong written and verbal communication skills, with close attention to detail — you&#39;ll be translating technical findings for both internal teams and customers.&lt;/li&gt;
&lt;li&gt;Genuine interest in ICS/OT cybersecurity and a drive to defend critical infrastructure, paired with the ability to pick up complex, industrial-specific concepts quickly and apply them.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Comfortable working independently in a remote environment while coordinating across distributed teams.&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;Flexibility to participate in shift-based coverage and occasional weekend/on-call work as needed. Note: The initial schedule will be Monday-Friday 8am-5pm, with on-call weekends (MDT for US, CEST for Europe, AEST for AUS). The schedule will later change to a 4 day/week, 10 hour shift model, which includes a day on the weekend. Shift schedules under the 4-day schedule will run Sunday-Wednesday and Wednesday-Saturday. Applicants will have the option to pick from either of the two shift schedules (Sunday-Wednesday or Wednesday-Saturday).&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:279}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:279}&quot;&gt;&lt;strong&gt;Preferred Qualifications&lt;/strong&gt;:&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience working on a Security Operations Center (SOC) team.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:279}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Familiarity with OT protocols (e.g., Modbus, DNP3, Ethernet/IP) and ICS environments.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;Applied knowledge of adversary tactics and frameworks relevant to OT (e.g., MITRE ATT&amp;amp;CK for ICS).&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;Hands-on lab or internship experience in cybersecurity operations, threat hunting, or digital forensics.&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;Experience in packet capture (PCAP) analysis or basic scripting (e.g., Python, Bash).&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:279}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Compensation&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559683&amp;quot;:0,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Salary: £60,000&lt;/span&gt;&lt;/li&gt;
